import React from 'react';
import { BrowserRouter, Routes, Route, Link, useNavigate, useLocation } from 'react-router-dom';
import Landing from './pages/Landing';
import Booking from './pages/Booking';
import Dashboard from './pages/Dashboard';
import Gallery from './pages/Gallery';
import TrimClub from './pages/TrimClub';
import Fidelidade from './pages/Fidelidade';

import Login from './pages/Login';
import LoginAdmin from './pages/LoginAdmin';
import Account from './pages/Account';
import { logout } from './api';

const Navbar = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const [isAuthenticated, setIsAuthenticated] = React.useState(!!localStorage.getItem('token'));

  React.useEffect(() => {
    setIsAuthenticated(!!localStorage.getItem('token'));
  }, [location]);

  const handleLogout = async () => {
    await logout();
    setIsAuthenticated(false);
    navigate('/login');
  };

  return (
    <nav style={{ padding: '1rem 2rem', borderBottom: '1px solid var(--color-border)', display: 'flex', gap: '2rem', alignItems: 'center' }}>
      <Link to="/" style={{ fontWeight: 800, fontSize: '1.5rem' }}>Trim</Link>
      <Link to="/galeria" style={{ color: 'var(--color-text-secondary)' }}>Galeria</Link>
      <Link to="/club" style={{ color: 'var(--color-text-secondary)' }}>Trim Club</Link>
      <Link to="/fidelidade" style={{ color: 'var(--color-text-secondary)' }}>Prêmios</Link>
      <div style={{ flex: 1 }} />
      {isAuthenticated && (
        <Link to="/conta" style={{ color: 'var(--color-text-secondary)' }}>Minha conta</Link>
      )}
      {isAuthenticated ? (
        <button onClick={handleLogout} style={{ padding: '0.5rem 1rem', background: 'transparent', border: '1px solid var(--color-border)', color: '#fff', borderRadius: '8px', fontWeight: 'bold', cursor: 'pointer' }}>Sair</button>
      ) : (
        <Link to="/login" style={{ padding: '0.5rem 1rem', background: 'var(--color-primary)', color: '#000', borderRadius: '8px', fontWeight: 'bold' }}>Entrar</Link>
      )}
    </nav>
  );
};

const App = () => {
  return (
    <BrowserRouter>
      <div className="app-container">
        <Routes>
          <Route path="/admin/login" element={
            <>
              <Navbar />
              <main className="main-content">
                <LoginAdmin />
              </main>
            </>
          } />
          <Route path="/admin/*" element={<Dashboard />} />
          <Route path="*" element={
            <>
              <Navbar />
              <main className="main-content">
                <Routes>
                  <Route path="/" element={<Landing />} />
                  <Route path="/login" element={<Login />} />
                  <Route path="/agenda" element={<Booking />} />
                  <Route path="/galeria" element={<Gallery />} />
                  <Route path="/club" element={<TrimClub />} />
                  <Route path="/fidelidade" element={<Fidelidade />} />
                  <Route path="/conta" element={<Account loginPath="/login" />} />
                </Routes>
              </main>
            </>
          } />
        </Routes>
      </div>
    </BrowserRouter>
  );
};

export default App;
import axios, { AxiosError, type InternalAxiosRequestConfig } from 'axios';

// Em `npm run dev`, sem VITE_API_URL, usa o backend local. O build exige a
// variável (ver vite.config.ts), então produção nunca cai neste padrão.
const API_URL = import.meta.env.VITE_API_URL || 'http://localhost:8000/api';

export const TOKEN_KEY = 'token';

// Rotas cujo 401 não se resolve com um refresh: credenciais erradas no login,
// sessão encerrada no próprio refresh, ou o logout (SPEC/2026-11-22-auth-refresh-logout.md).
const NO_REFRESH_ROUTES = ['/auth/login', '/auth/refresh', '/auth/logout'];

// withCredentials: o refresh token vai num cookie httpOnly que só o navegador conhece.
export const api = axios.create({
  baseURL: API_URL,
  withCredentials: true,
});

api.interceptors.request.use((config) => {
  const token = localStorage.getItem(TOKEN_KEY);
  if (token) {
    config.headers.Authorization = `Bearer ${token}`;
  }
  return config;
});

type RetriableConfig = InternalAxiosRequestConfig & { _refreshed?: boolean };

let pendingRefresh: Promise<string> | null = null;

/**
 * Troca o cookie de refresh por um access token novo e o guarda.
 * Vários pedidos que recebem 401 ao mesmo tempo compartilham uma única chamada.
 */
export function refreshAccessToken(): Promise<string> {
  pendingRefresh ??= api
    .post('/auth/refresh')
    .then((response) => {
      const token: string = response.data.access_token;
      localStorage.setItem(TOKEN_KEY, token);
      return token;
    })
    .finally(() => {
      pendingRefresh = null;
    });
  return pendingRefresh;
}

function canRefresh(config: RetriableConfig | undefined): config is RetriableConfig {
  if (!config || config._refreshed) return false;
  return !NO_REFRESH_ROUTES.some((route) => config.url?.endsWith(route));
}

api.interceptors.response.use(undefined, async (error: AxiosError) => {
  const config = error.config as RetriableConfig | undefined;
  if (error.response?.status !== 401 || !canRefresh(config)) {
    throw error;
  }
  config._refreshed = true;
  try {
    await refreshAccessToken();
  } catch {
    localStorage.removeItem(TOKEN_KEY);
    throw error;
  }
  return api(config);
});

/** Encerra a sessão no servidor (revoga o refresh token) e apaga o token local. */
export async function logout(): Promise<void> {
  try {
    await api.post('/auth/logout');
  } catch {
    // Sem rede ou sessão já encerrada: o token local sai do mesmo jeito.
  } finally {
    localStorage.removeItem(TOKEN_KEY);
  }
}

