import { useState } from 'react';
import styles from './AdminShared.module.css';
import ServiceForm from '../components/services/ServiceForm';
import ServiceRow from '../components/services/ServiceRow';
import formStyles from '../components/services/Services.module.css';
import {
  useAdminServices,
  type AdminService,
  type ServiceChanges,
  type ServiceInput,
} from '../hooks/useAdminServices';
import { apiErrorMessage } from '../utils/apiError';

// Gestão do catálogo pelo painel do admin (SPEC/2026-11-23-painel-servicos.md).

/** Formulário aberto: nenhum, o de criação ou o de edição de um serviço. */
type Editing = null | 'new' | AdminService;

const AdminServices = () => {
  const { services, status, loadError, reload, createService, updateService, deactivateService, reactivateService } =
    useAdminServices();
  const [editing, setEditing] = useState<Editing>(null);
  const [showInactive, setShowInactive] = useState(true);
  const [busyId, setBusyId] = useState<string | null>(null);
  const [message, setMessage] = useState('');
  const [actionError, setActionError] = useState('');

  const open = (target: Editing) => {
    setMessage('');
    setActionError('');
    setEditing(target);
  };

  const save = async (data: ServiceInput | ServiceChanges) => {
    if (editing === 'new') {
      await createService(data as ServiceInput);
      setMessage('Serviço criado.');
    } else if (editing) {
      await updateService(editing.id, data);
      setMessage('Serviço atualizado.');
    }
    setEditing(null);
  };

  /** Ação de uma linha: desabilita a linha enquanto roda e mostra o resultado no topo. */
  const runRowAction = async (service: AdminService, action: () => Promise<unknown>, done: string) => {
    setMessage('');
    setActionError('');
    setBusyId(service.id);
    try {
      await action();
      setMessage(done);
    } catch (error) {
      setActionError(apiErrorMessage(error, 'Não foi possível concluir a ação.'));
    } finally {
      setBusyId(null);
    }
  };

  const visible = showInactive ? services : services.filter((s) => s.is_active);

  let content;
  if (status === 'loading') {
    content = <p>Carregando serviços...</p>;
  } else if (status === 'error') {
    content = (
      <div>
        <p className={formStyles.error} role="alert">{loadError}</p>
        <button className={styles.btnAction} onClick={reload}>Tentar de novo</button>
      </div>
    );
  } else if (visible.length === 0) {
    content = <p>{services.length === 0 ? 'Nenhum serviço cadastrado.' : 'Nenhum serviço ativo.'}</p>;
  } else {
    content = (
      <table className={styles.table}>
        <thead>
          <tr>
            <th>Serviço</th>
            <th>Duração</th>
            <th>Preço</th>
            <th>Situação</th>
            <th>Ações</th>
          </tr>
        </thead>
        <tbody>
          {visible.map((service) => (
            <ServiceRow
              key={service.id}
              service={service}
              busy={busyId === service.id}
              onEdit={open}
              onDeactivate={(s) => runRowAction(s, () => deactivateService(s.id), 'Serviço desativado.')}
              onReactivate={(s) => runRowAction(s, () => reactivateService(s.id), 'Serviço reativado.')}
            />
          ))}
        </tbody>
      </table>
    );
  }

  return (
    <div className={styles.adminContainer}>
      <div className={styles.header}>
        <h2 className={styles.title}>✂️ Gestão de Serviços</h2>
        <button className={styles.btnAction} onClick={() => open('new')} disabled={status !== 'ready'}>
          + Novo Serviço
        </button>
      </div>

      {editing && (
        <ServiceForm
          // Trocar de serviço recria o formulário com os dados do novo.
          key={editing === 'new' ? 'new' : editing.id}
          service={editing === 'new' ? undefined : editing}
          onSave={save}
          onCancel={() => setEditing(null)}
        />
      )}

      {message && <p className={formStyles.info} role="status">{message}</p>}
      {actionError && <p className={formStyles.error} role="alert">{actionError}</p>}

      {status === 'ready' && services.length > 0 && (
        <label style={{ display: 'block', margin: '0 0 1rem' }}>
          <input type="checkbox" checked={showInactive} onChange={(e) => setShowInactive(e.target.checked)} />{' '}
          Mostrar desativados
        </label>
      )}

      {content}
    </div>
  );
};

export default AdminServices;
import { useCallback } from 'react';
import api from '../api';
import { useApiResource, type LoadStatus } from './useApiResource';

// Catálogo de serviços do painel do admin: carga pelo GET /services/admin e as ações sobre
// a API (SPEC/2026-11-23-painel-servicos.md). As ações devolvem o serviço como o backend
// gravou e lançam o erro da API, para quem chamou mostrar a mensagem.

export type AdminService = {
  id: string;
  name: string;
  description: string | null;
  /** O backend serializa o Decimal como texto ("35.00"). */
  price: string;
  duration_minutes: number;
  is_active: boolean;
};

/** Campos da criação, já no formato da API. */
export type ServiceInput = Pick<AdminService, 'name' | 'description' | 'price' | 'duration_minutes'>;
/** Alteração parcial: só os campos que mudaram. */
export type ServiceChanges = Partial<ServiceInput & Pick<AdminService, 'is_active'>>;

export type ServicesStatus = LoadStatus;

/** Mesma ordem do backend: alfabética, sem diferenciar maiúsculas. */
function sortByName(services: AdminService[]): AdminService[] {
  return [...services].sort((a, b) => a.name.localeCompare(b.name, 'pt-BR', { sensitivity: 'base' }));
}

const loadServices = async () => (await api.get<AdminService[]>('/services/admin')).data;

export function useAdminServices() {
  const {
    data: services,
    setData: setServices,
    status,
    loadError,
    reload,
  } = useApiResource(loadServices, [] as AdminService[], 'Não foi possível carregar os serviços.');

  /** Põe o serviço gravado na lista, no lugar do antigo ou como novo, mantendo a ordem. */
  const store = useCallback((saved: AdminService) => {
    setServices((current) => sortByName([...current.filter((s) => s.id !== saved.id), saved]));
    return saved;
  }, []);

  const createService = useCallback(
    async (input: ServiceInput) => store((await api.post<AdminService>('/services', input)).data),
    [store],
  );

  const updateService = useCallback(
    async (id: string, changes: ServiceChanges) =>
      store((await api.put<AdminService>(`/services/${id}`, changes)).data),
    [store],
  );

  /** O DELETE só desativa (soft delete) e não devolve corpo: a lista marca o serviço. */
  const deactivateService = useCallback(async (id: string) => {
    await api.delete(`/services/${id}`);
    setServices((current) => current.map((s) => (s.id === id ? { ...s, is_active: false } : s)));
  }, []);

  const reactivateService = useCallback(
    (id: string) => updateService(id, { is_active: true }),
    [updateService],
  );

  return {
    services,
    status,
    loadError,
    reload,
    createService,
    updateService,
    deactivateService,
    reactivateService,
  };
}
import { useCallback, useEffect, useState } from 'react';
import { apiErrorMessage } from '../utils/apiError';

// Carga de dados da API com "carregando", erro em português e "Tentar de novo". Usado pelo
// painel de serviços (SPEC/2026-11-23-painel-servicos.md) e por Meus agendamentos
// (SPEC/2026-11-25-meus-agendamentos.md). `setData` deixa quem usa atualizar a lista depois
// de uma ação, sem carregar de novo. `load` precisa ser estável (função do módulo ou
// useCallback): uma função nova a cada renderização carregaria de novo a cada renderização.

export type LoadStatus = 'loading' | 'ready' | 'error';

export function useApiResource<T>(load: () => Promise<T>, initial: T, fallbackError: string) {
  const [data, setData] = useState<T>(initial);
  const [status, setStatus] = useState<LoadStatus>('loading');
  const [loadError, setLoadError] = useState('');
  // Mudar o número pede uma nova carga ("Tentar de novo").
  const [attempt, setAttempt] = useState(0);

  useEffect(() => {
    let active = true;
    setStatus('loading');
    load()
      .then((loaded) => {
        if (!active) return;
        setData(loaded);
        setStatus('ready');
      })
      .catch((error) => {
        if (!active) return;
        setLoadError(apiErrorMessage(error, fallbackError));
        setStatus('error');
      });
    return () => {
      active = false;
    };
  }, [attempt, load, fallbackError]);

  const reload = useCallback(() => setAttempt((n) => n + 1), []);

  return { data, setData, status, loadError, reload };
}

