export type ProfileChanges = Partial<Pick<AccountUser, 'full_name' | 'phone' | 'avatar_url'>>;

export type AccountStatus = 'loading' | 'ready' | 'unauthenticated' | 'error';

export function useAccount() {
  const [user, setUser] = useState<AccountUser | null>(null);
  const [status, setStatus] = useState<AccountStatus>('loading');
  const [loadError, setLoadError] = useState('');

  useEffect(() => {
    let active = true;
    api
      .get<AccountUser>('/auth/me')
      .then((response) => {
        if (!active) return;
        setUser(response.data);
        setStatus('ready');
      })
      .catch((error) => {
        if (!active) return;
        // 401 depois do refresh falhar, ou 403 sem token: precisa entrar de novo.
        const code = isAxiosError(error) ? error.response?.status : undefined;
        if (code === 401 || code === 403) {
          setStatus('unauthenticated');
        } else {
          setLoadError(apiErrorMessage(error, 'Não foi possível carregar seus dados.'));
          setStatus('error');
        }
      });
    return () => {
      active = false;
    };
  }, []);

  /** Envia só os campos alterados e passa a mostrar o usuário como o backend devolveu. */
  const saveProfile = useCallback(async (changes: ProfileChanges) => {
    const response = await api.put<AccountUser>('/auth/me', changes);
    setUser(response.data);
    return response.data;
  }, []);

  /** Troca a senha e devolve a mensagem de confirmação do backend. */
  const changePassword = useCallback(async (currentPassword: string, newPassword: string) => {
    const response = await api.put<{ message: string }>('/auth/me/password', {
      current_password: currentPassword,
      new_password: newPassword,
    });
    return response.data.message;
  }, []);

  return { user, status, loadError, saveProfile, changePassword };
}
import { useState, type ReactNode } from 'react';
import shared from '../pages/AdminShared.module.css';

// Ação destrutiva com confirmação no próprio lugar: o botão vira a pergunta, "Confirmar" e
// "Voltar". Usado em "Desativar" serviço (SPEC/2026-11-23-painel-servicos.md) e em "Cancelar"
// agendamento (SPEC/2026-11-25-meus-agendamentos.md).

type Props = {
  /** Texto do botão que abre a confirmação. */
  label: string;
  /** Nome acessível do botão, quando o texto sozinho não basta (vários na mesma tela). */
  ariaLabel?: string;
  /** Pergunta mostrada no lugar do botão. */
  question: string;
  onConfirm: () => void;
  /** Uma ação está em andamento: os botões ficam desabilitados. */
  busy?: boolean;
  /** Outras ações, mostradas ao lado do botão e escondidas durante a confirmação. */
  children?: ReactNode;
};

const ConfirmButton = ({ label, ariaLabel, question, onConfirm, busy = false, children }: Props) => {
  const [confirming, setConfirming] = useState(false);

  if (confirming) {
    return (
      <>
        <span className={shared.confirmQuestion}>{question}</span>
        <button
          type="button"
          className={`${shared.btnIcon} ${shared.btnDanger}`}
          onClick={() => {
            setConfirming(false);
            onConfirm();
          }}
          disabled={busy}
        >
          Confirmar
        </button>
        <button type="button" className={shared.btnIcon} onClick={() => setConfirming(false)} disabled={busy}>
          Voltar
        </button>
      </>
    );
  }

  return (
    <>
      {children}
      <button
        type="button"
        className={`${shared.btnIcon} ${shared.btnDanger}`}
        aria-label={ariaLabel}
        onClick={() => setConfirming(true)}
        disabled={busy}
      >
        {label}
      </button>
    </>
  );
};

export default ConfirmButton;
