/* Formulário e linhas da tela de serviços do painel (SPEC/2026-11-23-painel-servicos.md). */

.form {
  background: var(--color-bg-elevated);
  border: 1px solid var(--color-border);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  margin-bottom: 2rem;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
}

.form h3 {
  grid-column: 1 / -1;
  margin: 0;
  font-size: 1.15rem;
  color: #fff;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.wide {
  grid-column: 1 / -1;
}

.field label {
  font-size: 0.9rem;
  color: var(--color-text-secondary);
}

.field input,
.field textarea {
  padding: 0.65rem 0.75rem;
  border-radius: var(--radius-md);
  border: 1px solid var(--color-border);
  background: var(--color-bg);
  color: var(--color-text-primary);
  font: inherit;
}

.field input:focus,
.field textarea:focus {
  outline: 2px solid var(--color-primary);
  outline-offset: 1px;
}

.actions {
  grid-column: 1 / -1;
  display: flex;
  justify-content: flex-end;
  gap: 0.75rem;
}

.primary {
  background: var(--color-primary);
  color: #000;
  border: none;
  padding: 0.6rem 1.4rem;
  border-radius: var(--radius-md);
  font-weight: 700;
  cursor: pointer;
}

.secondary {
  background: transparent;
  color: var(--color-text-secondary);
  border: 1px solid var(--color-border);
  padding: 0.6rem 1.4rem;
  border-radius: var(--radius-md);
  cursor: pointer;
}

.primary:disabled,
.secondary:disabled {
  opacity: 0.6;
  cursor: wait;
}

.error {
  grid-column: 1 / -1;
  color: var(--color-danger);
  margin: 0;
}

.info {
  grid-column: 1 / -1;
  color: var(--color-text-secondary);
  margin: 0;
}

.description {
  display: block;
  font-size: 0.85rem;
  color: var(--color-text-secondary);
  font-weight: 400;
  margin-top: 0.2rem;
}

.inactive td {
  opacity: 0.6;
}

.badge {
  display: inline-block;
  padding: 0.15rem 0.6rem;
  border-radius: var(--radius-full);
  font-size: 0.8rem;
  font-weight: 600;
}

.badgeActive {
  background: rgba(34, 197, 94, 0.15);
  color: var(--color-success);
}

.badgeInactive {
  background: rgba(255, 255, 255, 0.08);
  color: var(--color-text-secondary);
}

@media (max-width: 640px) {
  .form {
    grid-template-columns: 1fr;
  }
}
